using System.Text.Json;
using Connapse.Eval.Checks.Matching;
using FluentAssertions;

namespace Connapse.Eval.Tests.Checks;

/// <summary>
/// Checks the matching ports against values produced by the Python code they were ported from
/// (Fixtures/olmocr/expected.json, regenerated by generate_expected.py).
/// </summary>
[Trait("Category", "Unit")]
public class OlmOcrMatchingTests
{
    internal static readonly JsonElement Expected = JsonDocument.Parse(
        File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "Fixtures", "olmocr", "expected.json"))).RootElement;

    public static TheoryData<int> PyTextCases => Cases("pytext");
    public static TheoryData<int> FuzzCases => Cases("fuzz");
    public static TheoryData<int> NearMatchCases => Cases("near_matches");
    public static TheoryData<int> RepeatCases => Cases("repeats");
    public static TheoryData<int> TableCases => Cases("md_tables");
    public static TheoryData<int> SurrogateCases => Cases("surrogates");

    internal static TheoryData<int> Cases(string key)
    {
        TheoryData<int> data = [];
        for (int i = 0; i < Expected.GetProperty(key).GetArrayLength(); i++)
            data.Add(i);
        return data;
    }

    [Theory]
    [MemberData(nameof(PyTextCases))]
    public void PyText_MatchesPythonStrSemantics(int index)
    {
        JsonElement c = Expected.GetProperty("pytext")[index];
        string s = c.GetProperty("s").GetString()!;
        int[] points = PyText.CodePoints(s);

        PyText.Length(s).Should().Be(c.GetProperty("len").GetInt32());
        PyText.Lower(s).Should().Be(c.GetProperty("lower").GetString());
        points.Select(PyText.IsAlnum).Should().Equal(c.GetProperty("isalnum").EnumerateArray().Select(e => e.GetBoolean()));
        points.Select(PyText.IsSpace).Should().Equal(c.GetProperty("isspace").EnumerateArray().Select(e => e.GetBoolean()));
    }

    [Theory]
    [MemberData(nameof(FuzzCases))]
    public void RatioAndPartialRatio_MatchRapidFuzz(int index)
    {
        JsonElement c = Expected.GetProperty("fuzz")[index];
        string a = c.GetProperty("a").GetString()!;
        string b = c.GetProperty("b").GetString()!;

        RapidFuzz.Ratio(a, b).Should().BeApproximately(c.GetProperty("ratio").GetDouble(), 1e-9);
        RapidFuzz.PartialRatio(a, b).Should().BeApproximately(c.GetProperty("partial_ratio").GetDouble(), 1e-9);
    }

    [Theory]
    [MemberData(nameof(SurrogateCases))]
    public void LoneSurrogates_KeepTheirOwnCodePoints(int index)
    {
        JsonElement c = Expected.GetProperty("surrogates")[index];
        string a = FromUtf16Units(c.GetProperty("a"));
        string b = FromUtf16Units(c.GetProperty("b"));

        PyText.Length(a).Should().Be(c.GetProperty("len").GetInt32());
        PyText.CodePoints(PyText.Lower(a)).Should().Equal(c.GetProperty("lower").EnumerateArray().Select(e => e.GetInt32()));
        RapidFuzz.Ratio(a, b).Should().BeApproximately(c.GetProperty("ratio").GetDouble(), 1e-9);
        RapidFuzz.PartialRatio(a, b).Should().BeApproximately(c.GetProperty("partial_ratio").GetDouble(), 1e-9);
    }

    // Python code points to a .NET string: astral code points become surrogate pairs, lone surrogates stay single units.
    private static string FromUtf16Units(JsonElement codePoints) =>
        PyText.FromCodePoints(codePoints.EnumerateArray().Select(e => e.GetInt32()).ToArray());

    [Theory]
    [MemberData(nameof(NearMatchCases))]
    public void FindNearMatches_MatchesFuzzysearch(int index)
    {
        JsonElement c = Expected.GetProperty("near_matches")[index];

        IReadOnlyList<NearMatch> matches = FuzzySearch.FindNearMatches(
            c.GetProperty("sub").GetString()!, c.GetProperty("seq").GetString()!, c.GetProperty("max_l_dist").GetInt32());

        matches.Select(m => new[] { m.Start, m.End, m.Dist }).Should().BeEquivalentTo(
            c.GetProperty("matches").EnumerateArray().Select(m => m.EnumerateArray().Select(e => e.GetInt32()).ToArray()),
            o => o.WithStrictOrdering());
    }

    [Theory]
    [MemberData(nameof(RepeatCases))]
    public void NgramRepeats_MatchesRepeatDetector(int index)
    {
        JsonElement c = Expected.GetProperty("repeats")[index];

        RepeatDetector.NgramRepeats(c.GetProperty("s").GetString()!, 5)
            .Should().Equal(c.GetProperty("repeats").EnumerateArray().Select(e => e.GetInt32()));
    }

    [Theory]
    [MemberData(nameof(TableCases))]
    public void ParseMarkdownTables_MatchesTableParsing(int index)
    {
        JsonElement c = Expected.GetProperty("md_tables")[index];
        IReadOnlyList<TableData> tables = MarkdownTables.Parse(c.GetProperty("md").GetString()!);
        JsonElement[] expected = c.GetProperty("tables").EnumerateArray().ToArray();

        tables.Should().HaveCount(expected.Length);
        for (int t = 0; t < tables.Count; t++)
        {
            TableData table = tables[t];
            JsonElement e = expected[t];
            table.CellText.ToDictionary(p => Key(p.Key), p => p.Value)
                .Should().Equal(e.GetProperty("cells").EnumerateObject().ToDictionary(p => p.Name, p => p.Value.GetString()!));
            table.HeadingCells.Select(Key).Order(StringComparer.Ordinal)
                .Should().Equal(e.GetProperty("headings").EnumerateArray().Select(x => x.GetString()!).Order(StringComparer.Ordinal));
            table.IsRectangular.Should().Be(e.GetProperty("rectangular").GetBoolean());
            AssertRelation(table.CellText.Keys, table.Up.GetValueOrDefault, e.GetProperty("up"));
            AssertRelation(table.CellText.Keys, table.Down.GetValueOrDefault, e.GetProperty("down"));
            AssertRelation(table.CellText.Keys, table.Left.GetValueOrDefault, e.GetProperty("left"));
            AssertRelation(table.CellText.Keys, table.Right.GetValueOrDefault, e.GetProperty("right"));
            AssertRelation(table.CellText.Keys, table.TopHeadings, e.GetProperty("top_heading"));
            AssertRelation(table.CellText.Keys, table.LeftHeadings, e.GetProperty("left_heading"));
        }
    }

    private static string Key(CellPos p) => $"{p.Row},{p.Col}";

    private static void AssertRelation(IEnumerable<CellPos> cells, Func<CellPos, IReadOnlySet<CellPos>?> relation, JsonElement expected)
    {
        foreach (CellPos cell in cells)
            (relation(cell) ?? new HashSet<CellPos>()).Select(Key).Order(StringComparer.Ordinal).Should().Equal(
                expected.GetProperty(Key(cell)).EnumerateArray().Select(x => x.GetString()!).Order(StringComparer.Ordinal),
                $"relation of cell {Key(cell)}");
    }
}
